CREATE TABLE posts ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, caption VARCHAR(2200), location TEXT, is_comments_disabled BOOLEAN NOT NULL DEFAULT FALSE, is_likes_hidden BOOLEAN NOT NULL DEFAULT FALSE, likes_count INTEGER NOT NULL DEFAULT 0, comments_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ,
CONSTRAINT POSTS_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE );
CREATE INDEX idx_posts_profile ON posts(profile_id, created_at DESC) WHERE deleted_at IS NULL; CREATE INDEX idx_posts_feed ON posts(created_at DESC) WHERE deleted_at IS NULL;
